	}
}

func TestCLIHelpAndVersion(t *testing.T) {
	for _, tc := range []struct {
		args []string
		want string
	}{
		{[]string{"help"}, "preview"},
		{[]string{"version"}, "0.2.0"},
		{[]string{"demo"}, "roots"},
