package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
	"time"
)

func main() {
	mode := os.Args[1]
	f, _ := os.OpenFile("/tmp/flockexp/L.lock", os.O_CREATE|os.O_RDWR, 0o644)
	if mode == "holder" {
		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
			panic(err)
		}
		fmt.Println("held")
		time.Sleep(3 * time.Second)
		return
	}
	// waiter: block
	go func() {
		syscall.Flock(int(f.Fd()), syscall.LOCK_EX)
		fmt.Println("acquired")
	}()
	time.Sleep(500 * time.Millisecond)
	count := countBlockedOn(f)
	fmt.Printf("blocked waiters on inode: %d\n", count)
}

func countBlockedOn(f *os.File) int {
	fi, _ := f.Stat()
	st := fi.Sys().(*syscall.Stat_t)
	inode := strconv.FormatUint(st.Ino, 10)
	dev := st.Dev
	maj := (dev >> 8)
	min := dev & 0xff
	want := fmt.Sprintf("%02x:%02x:%s", maj, min, inode)
	lf, err := os.Open("/proc/locks")
	if err != nil {
		panic(err)
	}
	defer lf.Close()
	n := 0
	sc := bufio.NewScanner(lf)
	for sc.Scan() {
		line := sc.Text()
		fields := strings.Fields(line)
		// e.g. 1: FLOCK  ADVISORY  WRITE 1234 fd:00:1234 0 EOF
		if len(fields) >= 6 && fields[1] == "FLOCK" {
			if strings.HasSuffix(fields[5], ":"+inode) {
				_ = want
				n++
				fmt.Printf("  MATCH: %s\n", line)
			}
		}
	}
	return n
}
EOF
