//go:build unix

package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"syscall"
	"testing"
)

func TestDebugGate(t *testing.T) {
	dir := t.TempDir()
	gp := filepath.Join(dir, "g.json")
	os.WriteFile(gp, []byte(`{"datasets":[{"name":"A","upstreams":[]}]}`), 0o644)
	target := filepath.Join(dir, "snap.json")
	lock := target + ".lock"

	gate := holdLockGate(t, lock)
	t.Logf("helper pid=%d bin=%s", gate.cmd.Process.Pid, snapshotCLIBin)

	fi, _ := os.Stat(lock)
	st := fi.Sys().(*syscall.Stat_t)
	t.Logf("lock inode=%d", st.Ino)

	var o1, e1, o2, e2 bytes.Buffer
	c1 := exec.Command(snapshotCLIBin, "snapshot", gp, target)
	c1.Stdout, c1.Stderr = &o1, &e1
	c2 := exec.Command(snapshotCLIBin, "snapshot", gp, target)
	c2.Stdout, c2.Stderr = &o2, &e2
	if err := c1.Start(); err != nil {
		t.Fatal(err)
	}
	if err := c2.Start(); err != nil {
		t.Fatal(err)
	}
	t.Logf("c1 pid=%d c2 pid=%d", c1.Process.Pid, c2.Process.Pid)

	// sleep like the waiter does, then dump everything
	waitSecs := 2
	for i := 0; i < waitSecs*4; i++ {
		alive := func(pid int) string {
			p, _ := os.FindProcess(pid)
			if p.Signal(syscall.Signal(0)) == nil {
				return "alive"
			}
			return "dead"
		}
		t.Logf("t+%vms c1=%s c2=%s helper=%s", i*250,
			alive(c1.Process.Pid), alive(c2.Process.Pid), alive(gate.cmd.Process.Pid))
		dumpLocks(t, st.Ino)
		blocked := blockedWaiterPIDs(t, lock)
		t.Logf("blockedWaiterPIDs=%v", blocked)
		if blocked[c1.Process.Pid] && blocked[c2.Process.Pid] {
			break
		}
	}
	t.Logf("c1 out=%q err=%q", o1.String(), e1.String())
	t.Logf("c2 out=%q err=%q", o2.String(), e2.String())
	entries, _ := os.ReadDir(dir)
	for _, en := range entries {
		t.Logf("dir entry: %s", en.Name())
	}
	gate.release()
	c1.Wait()
	c2.Wait()
	fmt.Println("debug done")
}

func dumpLocks(t *testing.T, ino uint64) {
	data, _ := os.ReadFile("/proc/locks")
	suffix := ":" + fmt.Sprintf("%d", ino)
	for _, line := range bytes.Split(data, []byte("\n")) {
		if bytes.Contains(line, []byte(suffix)) {
			t.Logf("LOCKLINE: %s", string(line))
		}
	}
}

