//go:build unix

package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"syscall"
	"testing"
	"time"
)

const diagMode = "--chainledger-test-diag"

// diagSelf prints pid, namespaces, and the lock path inode this process sees.
func diagSelf(args []string) int {
	lock := args[0]
	pid := os.Getpid()
	mnt, _ := os.Readlink("/proc/self/ns/mnt")
	pidns, _ := os.Readlink("/proc/self/ns/pid")
	cwd, _ := os.Getwd()
	fi, err := os.Stat(lock)
	inode := uint64(0)
	if err == nil {
		inode = fi.Sys().(*syscall.Stat_t).Ino
	}
	f, oerr := os.OpenFile(lock, os.O_CREATE|os.O_RDWR, 0o644)
	flockRes := "no-open"
	if oerr == nil {
		if e := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); e != nil {
			flockRes = "BUSY"
		} else {
			flockRes = "ACQUIRED"
		}
	}
	fmt.Printf("pid=%d mnt=%s pidns=%s cwd=%s inode=%d statErr=%v openErr=%v flock=%s\n",
		pid, mnt, pidns, cwd, inode, err, oerr, flockRes)
	time.Sleep(3 * time.Second)
	return 0
}

func TestDebugNS(t *testing.T) {
	if len(os.Args) >= 2 && os.Args[1] == diagMode {
		os.Exit(diagSelf(os.Args[2:]))
	}
	dir := t.TempDir()
	lock := filepath.Join(dir, "snap.lock")
	exe, _ := os.Executable()

	// Parent's own view.
	pfi, _ := os.Stat(lock)
	t.Logf("PARENT pid=%d mnt=%s pidns=%s lock-inode-before-exists", os.Getpid(),
		mustReadlink("/proc/self/ns/mnt"), mustReadlink("/proc/self/ns/pid"))

	h := exec.Command(exe, diagMode, lock)
	h.Stdout, h.Stderr = os.Stdout, os.Stderr
	h.Start()
	t.Logf("spawned holder pid=%d", h.Process.Pid)
	time.Sleep(500 * time.Millisecond)

	// Now a second process tries.
	nb := exec.Command(exe, diagMode, lock)
	out, _ := nb.CombinedOutput()
	t.Logf("SECOND process output:\n%s", string(out))
	h.Wait()
	_ = pfi
}

func mustReadlink(p string) string {
	v, err := os.Readlink(p)
	if err != nil {
		return "err:" + err.Error()
	}
	return v
}

