	os.Stdout.Sync()
	time.Sleep(5 * time.Second)
	return 0
}

// hold via the product acquireLock (struct-wrapped, deferred release).
func holdAcquire(lock string) int {
	l, err := acquireLock(lock)
	if err != nil {
		fmt.Println("acquire-err", err)
		return 1
	}
	defer l.release()
	fmt.Println("locked-acquire")
	os.Stdout.Sync()
	time.Sleep(5 * time.Second)
	return 0
}

func runDiagHolder(args []string) int {
