		pipe, _ := h.StdoutPipe()
		h.Start()
		buf := make([]byte, 64)
		pipe.Read(buf)
		time.Sleep(300 * time.Millisecond)

		// probe from a second process
		out, _ := exec.Command(exe, nbTryMode, lock).CombinedOutput()
		// holder lock visible in /proc/locks?
		visible := false
		if data, err := os.ReadFile("/proc/locks"); err == nil {
			for _, line := range strings.Split(string(data), "\n") {
				if strings.Contains(line, " "+strconv.Itoa(h.Process.Pid)+" ") && strings.Contains(line, "FLOCK") {
