)

func TestDebugThreeHolders(t *testing.T) {
	exe, _ := os.Executable()

	// (1) real gate helper via holdLockGate
	dir1 := t.TempDir()
	lock1 := dir1 + "/snap.lock"
	g1 := holdLockGate(t, lock1)
	time.Sleep(200 * time.Millisecond)
	out1, _ := exec.Command(exe, nbTryMode, lock1).CombinedOutput()
	t.Logf("[holdLockGate/runLockHelper] pid=%d probe=%s", g1.cmd.Process.Pid, strings.TrimSpace(string(out1)))
	dumpHolderLocks(t, g1.cmd.Process.Pid)

	// (2) inline acquire helper mode
	dir2 := t.TempDir()
	lock2 := dir2 + "/snap.lock"
	h2 := exec.Command(exe, holdAcquireMode, lock2)
	h2.Stderr = os.Stderr
	p2, _ := h2.StdoutPipe()
