}

func dumpHolderLocks(t *testing.T, pid int) {
	data, err := os.ReadFile("/proc/locks")
	if err != nil {
		t.Logf("read /proc/locks err=%v", err)
		return
	}
	any := false
	for _, line := range strings.Split(string(data), "\n") {
		if strings.Contains(line, " "+strconv.Itoa(pid)+" ") {
			t.Logf("  /proc/locks pid %d: %s", pid, line)
			any = true
		}
	}
	if !any {
		t.Logf("  /proc/locks pid %d: <no lock lines at all>", pid)
	}
}

