//go:build unix

package main

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"time"
)

const holdInlineMode = "--diag-hold-inline"
const holdAcquireMode = "--diag-hold-acquire"

// hold inline: open + flock in main, keep *os.File in a local, sleep.
func holdInline(lock string) int {
	f, err := os.OpenFile(lock, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		fmt.Println("open-err", err)
		return 1
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
		fmt.Println("flock-err", err)
		return 1
	}
	fmt.Println("locked-inline")
	os.Stdout.Sync()
	time.Sleep(5 * time.Second)
	return 0
}

// hold via the product acquireLock (struct-wrapped, deferred release).
func holdAcquire(lock string) int {
	l, err := acquireLock(lock)
	if err != nil {
		fmt.Println("acquire-err", err)
		return 1
	}
	defer l.release()
	fmt.Println("locked-acquire")
	os.Stdout.Sync()
	time.Sleep(5 * time.Second)
	return 0
}

func runDiagHolder(args []string) int {
	if len(args) != 2 {
		return 2
	}
	switch args[0] {
	case holdInlineMode:
		return holdInline(args[1])
	case holdAcquireMode:
		return holdAcquire(args[1])
	}
	return 2
}

func TestDebugHoldComparison(t *testing.T) {
	if len(os.Args) >= 2 && (os.Args[1] == holdInlineMode || os.Args[1] == holdAcquireMode) {
		os.Exit(runDiagHolder(os.Args[1:]))
	}
	exe, _ := os.Executable()
	for _, mode := range []string{holdInlineMode, holdAcquireMode} {
		dir := t.TempDir()
		lock := dir + "/snap.lock"
		h := exec.Command(exe, mode, lock)
		h.Stderr = os.Stderr
		pipe, _ := h.StdoutPipe()
		h.Start()
		buf := make([]byte, 64)
		pipe.Read(buf)
		time.Sleep(300 * time.Millisecond)

		// probe from a second process
		out, _ := exec.Command(exe, nbTryMode, lock).CombinedOutput()
		// holder lock visible in /proc/locks?
		visible := false
		if data, err := os.ReadFile("/proc/locks"); err == nil {
			for _, line := range strings.Split(string(data), "\n") {
				if strings.Contains(line, " "+strconv.Itoa(h.Process.Pid)+" ") && strings.Contains(line, "FLOCK") {
					visible = true
				}
			}
		}
		t.Logf("mode=%s probe=%s holderLockInProcLocks=%v", mode, strings.TrimSpace(string(out)), visible)
		h.Process.Kill()
		h.Wait()
	}
}

