41	// lockHelperMode is the hidden argument under which the test binary itself
42	// acts as an external lock holder, reusing the product's own acquireLock.
43	const lockHelperMode = "--chainledger-test-lock-helper"
44	
45	// lockHelperTTL bounds a helper whose parent died before killing it; a normal
46	// test always kills it explicitly far sooner.
47	const lockHelperTTL = 60 * time.Second
48	
49	// nbTryMode is a diagnostic helper: take the lock non-blocking and report
50	// whether it was already held.
51	const nbTryMode = "--chainledger-test-nb-try"
52	
53	// runNonBlockingLockTry tries a non-blocking exclusive flock and prints
54	// LOCKED-BY-OTHER (exit 0) when another process holds it, or LOCK-FREE (exit
55	// 0) when it does not.
56	func runNonBlockingLockTry(args []string) int {
57		if len(args) != 1 {
58			fmt.Fprintln(os.Stderr, "usage: test-binary", nbTryMode, "<lock-file>")
59			return 2
60		}
61		f, err := os.OpenFile(args[0], os.O_CREATE|os.O_RDWR, 0o644)
62		if err != nil {
63			fmt.Println("open-error", err)
64			return 3
65		}
66		defer f.Close()
67		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
68			fmt.Println("LOCKED-BY-OTHER")
69			return 0
70		}
71		fmt.Println("LOCK-FREE")
72		return 0
73	}
