// lockHelperMode is the hidden argument under which the test binary itself
// acts as an external lock holder, reusing the product's own acquireLock.
const lockHelperMode = "--chainledger-test-lock-helper"

// lockHelperTTL bounds a helper whose parent died before killing it; a normal
// test always kills it explicitly far sooner.
const lockHelperTTL = 60 * time.Second

// nbTryMode is a diagnostic helper: take the lock non-blocking and report
// whether it was already held.
const nbTryMode = "--chainledger-test-nb-try"

// runNonBlockingLockTry tries a non-blocking exclusive flock and prints
// LOCKED-BY-OTHER (exit 0) when another process holds it, or LOCK-FREE (exit
// 0) when it does not.
func runNonBlockingLockTry(args []string) int {
	if len(args) != 1 {
		fmt.Fprintln(os.Stderr, "usage: test-binary", nbTryMode, "<lock-file>")
		return 2
	}
	f, err := os.OpenFile(args[0], os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		fmt.Println("open-error", err)
		return 3
	}
	defer f.Close()
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		fmt.Println("LOCKED-BY-OTHER")
		return 0
	}
	fmt.Println("LOCK-FREE")
	return 0
}

// snapshotCLIBin is the freshly built real command binary, shared by every
// test so `go build` runs once per `go test` invocation.
var snapshotCLIBin string

// TestMain builds the command binary once and also implements the external
// lock-holder helper mode (the test binary re-enters here as a subprocess).
func TestMain(m *testing.M) {
	if len(os.Args) >= 2 && os.Args[1] == lockHelperMode {
		os.Exit(runLockHelper(os.Args[2:]))
	}
	if len(os.Args) >= 2 && os.Args[1] == nbTryMode {
		os.Exit(runNonBlockingLockTry(os.Args[2:]))
	}
	if len(os.Args) >= 2 && (os.Args[1] == holdInlineMode || os.Args[1] == holdAcquireMode) {
		os.Exit(runDiagHolder(os.Args[1:]))
	}

	dir, err := os.MkdirTemp("", "chainledger-snapshot-bin-")
	if err != nil {
		fmt.Fprintln(os.Stderr, "cannot make temp build dir:", err)
		os.Exit(1)
	}
	snapshotCLIBin = filepath.Join(dir, "chainledger")
	build := exec.Command("go", "build", "-o", snapshotCLIBin, ".")
	build.Stderr = os.Stderr
	if err := build.Run(); err != nil {
		fmt.Fprintln(os.Stderr, "cannot build chainledger test binary:", err)
		os.RemoveAll(dir)
		os.Exit(1)
	}

	code := m.Run()
	os.RemoveAll(dir)
	os.Exit(code)
}

// runLockHelper acquires the exact flock the snapshot command acquires, prints
// "locked" so the parent knows the gate is closed, and holds it until killed.
func runLockHelper(args []string) int {
	if len(args) != 1 {
		fmt.Fprintln(os.Stderr, "usage: test-binary", lockHelperMode, "<lock-file>")
		return 2
	}
	lock, err := acquireLock(args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, "helper cannot acquire lock:", err)
