1	//go:build unix
2	
3	package main
4	
5	// Cross-process regression coverage for concurrent `snapshot` saves.
6	//
7	// The in-process test TestCLISnapshotConcurrentSameContent only proves that
8	// goroutines inside one command process serialize. These tests instead launch
9	// two INDEPENDENT command binaries that submit to the SAME snapshot target with
10	// overlapping execution:
11	//
12	//   - an external helper process first takes the sibling flock the snapshot
13	//     command uses, so neither command can enter its check-then-write section;
14	//   - both commands are started and confirmed (via /proc/locks) blocked on that
15	//     very lock before the helper is killed and the kernel hands the lock to
16	//     one of them;
17	//   - the two saves are therefore simultaneous submissions that race the lock,
18	//     never two saves run one after the other, and no winner is preselected.
19	//
20	// Everything asserted here is observable user behavior: per-command exit code,
21	// exact stdout/stderr, and the final snapshot file. No chain network is used.
22	
23	import (
24		"bufio"
25		"bytes"
26		"fmt"
27		"os"
28		"os/exec"
29		"path/filepath"
30		"reflect"
31		"sort"
32		"strconv"
33		"strings"
34		"syscall"
35		"testing"
36		"time"
37	
38		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
39	)
40	
41	// lockHelperMode is the hidden argument under which the test binary itself
42	// acts as an external lock holder, reusing the product's own acquireLock.
43	const lockHelperMode = "--chainledger-test-lock-helper"
44	
45	// lockHelperTTL bounds a helper whose parent died before killing it; a normal
46	// test always kills it explicitly far sooner.
47	const lockHelperTTL = 60 * time.Second
48	
49	// snapshotCLIBin is the freshly built real command binary, shared by every
50	// test so `go build` runs once per `go test` invocation.
51	var snapshotCLIBin string
52	
53	// TestMain builds the command binary once and also implements the external
54	// lock-holder helper mode (the test binary re-enters here as a subprocess).
55	func TestMain(m *testing.M) {
56		if len(os.Args) >= 2 && os.Args[1] == lockHelperMode {
57			os.Exit(runLockHelper(os.Args[2:]))
58		}
59	
60		dir, err := os.MkdirTemp("", "chainledger-snapshot-bin-")
61		if err != nil {
62			fmt.Fprintln(os.Stderr, "cannot make temp build dir:", err)
63			os.Exit(1)
64		}
65		snapshotCLIBin = filepath.Join(dir, "chainledger")
66		build := exec.Command("go", "build", "-o", snapshotCLIBin, ".")
67		build.Stderr = os.Stderr
68		if err := build.Run(); err != nil {
69			fmt.Fprintln(os.Stderr, "cannot build chainledger test binary:", err)
70			os.RemoveAll(dir)
71			os.Exit(1)
72		}
73	
74		code := m.Run()
75		os.RemoveAll(dir)
76		os.Exit(code)
77	}
78	
79	// runLockHelper takes an exclusive kernel flock on the very sibling lock file
80	// the snapshot command uses. It deliberately performs the flock with a raw
81	// syscall rather than reusing the product's acquireLock: the gate is test
82	// infrastructure and must keep working even when a deliberate fault disables
83	// locking inside the command under test. A flock on the same file inode is
84	// kernel-level and code-agnostic, so this still blocks the commands' own
85	// acquireLock calls. It prints "locked" once the gate is closed and holds the
86	// lock until killed.
87	func runLockHelper(args []string) int {
88		if len(args) != 1 {
89			fmt.Fprintln(os.Stderr, "usage: test-binary", lockHelperMode, "<lock-file>")
90			return 2
91		}
92		f, err := os.OpenFile(args[0], os.O_CREATE|os.O_RDWR, 0o644)
93		if err != nil {
94			fmt.Fprintln(os.Stderr, "helper cannot open lock:", err)
95			return 1
96		}
97		defer f.Close()
98		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
99			fmt.Fprintln(os.Stderr, "helper cannot flock:", err)
100			return 1
101		}
102		defer syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
103		// os.Stdout is an unbuffered os.File, so Println reaches the pipe
104		// immediately; do NOT call os.Stdout.Sync() — fsync on a pipe fails with
105		// EINVAL and must not abort the helper before it has held the lock.
106		fmt.Println("locked")
107		time.Sleep(lockHelperTTL)
108		return 0
109	}
110	
111	// lockGate is an external process holding the snapshot target's lock. Releasing
112	// the gate (killing the holder) lets the kernel grant the lock to exactly one
113	// of the waiting commands.
114	type lockGate struct {
115		cmd *exec.Cmd
116	}
117	
118	// holdLockGate starts the helper and blocks until it has confirmed (by
119	// printing "locked") that it holds the lock, so any snapshot command started
120	// afterwards is guaranteed to block.
121	func holdLockGate(t *testing.T, lockPath string) *lockGate {
122		t.Helper()
123		exe, err := os.Executable()
124		if err != nil {
125			t.Fatalf("locate test binary: %v", err)
126		}
127		cmd := exec.Command(exe, lockHelperMode, lockPath)
128		stdout, err := cmd.StdoutPipe()
129		if err != nil {
130			t.Fatalf("helper stdout pipe: %v", err)
131		}
132		cmd.Stderr = os.Stderr
133		if err := cmd.Start(); err != nil {
134			t.Fatalf("start lock helper: %v", err)
135		}
136		t.Cleanup(func() {
137			_ = cmd.Process.Kill()
138			_ = cmd.Wait()
139		})
140	
141		ready := make(chan bool, 1)
142		go func() {
143			sc := bufio.NewScanner(stdout)
144			ready <- sc.Scan() && sc.Text() == "locked"
145		}()
146		select {
147		case ok := <-ready:
148			if !ok {
149				t.Fatal("lock helper exited without reporting the lock")
150			}
151		case <-time.After(10 * time.Second):
152			t.Fatal("lock helper never acquired the lock")
153		}
154		return &lockGate{cmd: cmd}
155	}
156	
157	// release kills the holder; its process death releases the flock atomically.
158	func (g *lockGate) release() {
159		_ = g.cmd.Process.Kill()
160		_ = g.cmd.Wait()
161	}
162	
163	// blockedWaiterPIDs returns the PIDs of processes with an FLOCK request queued
164	// (the "/proc/locks" lines starting with "->") on the given lock file's inode.
165	// The holder's own granted lock has no "->" prefix and is excluded.
166	func blockedWaiterPIDs(t *testing.T, lockPath string) map[int]bool {
167		t.Helper()
168		fi, err := os.Stat(lockPath)
169		if err != nil {
170			t.Fatalf("stat lock file: %v", err)
171		}
172		st, ok := fi.Sys().(*syscall.Stat_t)
173		if !ok {
174			t.Fatalf("lock file stat is not a unix stat_t: %T", fi.Sys())
175		}
176		inodeSuffix := ":" + strconv.FormatUint(st.Ino, 10)
177	
178		data, err := os.ReadFile("/proc/locks")
179		if err != nil {
180			t.Fatalf("read /proc/locks: %v", err)
181		}
182		pids := make(map[int]bool)
183		for _, line := range strings.Split(string(data), "\n") {
184			fields := strings.Fields(line)
185			// A blocked waiter looks like:
186			// "772: -> FLOCK ADVISORY WRITE 1234 103:02:2887301 0 EOF"
187			// while the holder's granted line has no "->". Locate the arrow and
188			// the FLOCK record that follows it.
189			arrow := -1
190			for i, f := range fields {
191				if f == "->" {
192					arrow = i
193					break
194				}
195			}
196			if arrow < 0 {
197				continue
198			}
199			flockIdx := -1
200			for i := arrow + 1; i < len(fields); i++ {
201				if fields[i] == "FLOCK" {
202					flockIdx = i
203					break
204				}
205			}
206			if flockIdx < 0 || flockIdx+4 >= len(fields) {
207				continue
208			}
209			// Layout after FLOCK: ADVISORY WRITE <pid> <dev>:<inode> 0 EOF
210			pidField, idField := fields[flockIdx+3], fields[flockIdx+4]
211			// Match the lock inode; the waiter PID is in any case one of our
212			// command processes, which never flock any other file.
213			if !strings.HasSuffix(idField, inodeSuffix) {
214				continue
215			}
216			if pid, err := strconv.Atoi(pidField); err == nil {
217				pids[pid] = true
218			}
219		}
220		return pids
221	}
222	
223	// waitUntilAllBlocked polls until every expected PID is queued waiting on the
224	// lock file. It proves both commands are simultaneously parked at the start of
225	// their serialized section before the test lets the race resolve.
226	func waitUntilAllBlocked(t *testing.T, lockPath string, want map[int]bool) {
227		t.Helper()
228		deadline := time.Now().Add(10 * time.Second)
229		for time.Now().Before(deadline) {
230			got := blockedWaiterPIDs(t, lockPath)
231			missing := false
232			for pid := range want {
233				if !got[pid] {
234					missing = true
235				}
236			}
237			if !missing {
238				return
239			}
240			time.Sleep(5 * time.Millisecond)
241		}
242		t.Fatalf("timed out waiting for commands %v to block on %q; blocked waiters: %v",
243			want, lockPath, blockedWaiterPIDs(t, lockPath))
244	}
245	
246	// procResult is everything observable about one finished command process.
247	type procResult struct {
248		label       string
249		stdout      string
250		stderr      string
251		exitCode    int
252		sourceGraph string // path of the graph the command read
253	}
254	
255	// waitCommandProcess waits for cmd to finish, failing the test if it hangs.
256	func waitCommandProcess(t *testing.T, cmd *exec.Cmd) {
257		t.Helper()
258		done := make(chan error, 1)
259		go func() { done <- cmd.Wait() }()
260		select {
261		case <-done:
262		case <-time.After(30 * time.Second):
263			_ = cmd.Process.Kill()
264			t.Fatalf("snapshot command %d did not finish after the lock was released", cmd.Process.Pid)
265		}
266	}
267	
268	// launchConcurrentSnapshotPair runs two independent snapshot command binaries
269	// against the same target with genuinely overlapping execution. Both are
270	// blocked together on the external gate before either can inspect the target;
271	// the gate is then released and the kernel decides the order. The returned
272	// results are bound to firstGraph / secondGraph in launch order.
273	func launchConcurrentSnapshotPair(t *testing.T, target, firstGraph, secondGraph string) (procResult, procResult) {
274		t.Helper()
275		lockPath := target + ".lock"
276		gate := holdLockGate(t, lockPath)
277	
278		var out1, err1, out2, err2 bytes.Buffer
279		cmd1 := exec.Command(snapshotCLIBin, "snapshot", firstGraph, target)
280		cmd1.Stdout, cmd1.Stderr = &out1, &err1
281		cmd2 := exec.Command(snapshotCLIBin, "snapshot", secondGraph, target)
282		cmd2.Stdout, cmd2.Stderr = &out2, &err2
283	
284		if err := cmd1.Start(); err != nil {
285			t.Fatalf("start first snapshot command: %v", err)
286		}
287		if err := cmd2.Start(); err != nil {
288			t.Fatalf("start second snapshot command: %v", err)
289		}
290		waitUntilAllBlocked(t, lockPath, map[int]bool{
291			cmd1.Process.Pid: true,
292			cmd2.Process.Pid: true,
293		})
294	
295		gate.release()
296		waitCommandProcess(t, cmd1)
297		waitCommandProcess(t, cmd2)
298	
299		return procResult{
300				label:       "first",
301				stdout:      out1.String(),
302				stderr:      err1.String(),
303				exitCode:    cmd1.ProcessState.ExitCode(),
304				sourceGraph: firstGraph,
305			}, procResult{
306				label:       "second",
307				stdout:      out2.String(),
308				stderr:      err2.String(),
309				exitCode:    cmd2.ProcessState.ExitCode(),
310				sourceGraph: secondGraph,
311			}
312	}
313	
314	// mustSnapshotFromGraph builds the expected snapshot for a graph JSON string
315	// the same way the command does, so the test can compare content id and the
316	// normalized graph without hardcoding hashes.
317	func mustSnapshotFromGraph(t *testing.T, graphJSON string) *chainledger.SnapshotFile {
318		t.Helper()
319		graph, err := chainledger.UnmarshalGraphFile([]byte(graphJSON))
320		if err != nil {
321			t.Fatalf("invalid reference graph: %v", err)
322		}
323		snap, err := chainledger.BuildSnapshot(graph)
324		if err != nil {
325			t.Fatalf("build reference snapshot: %v", err)
326		}
327		return snap
328	}
329	
330	// rootNames traces dataset in snap and returns the sorted root sources the
331	// stored lineage actually reaches.
332	func rootNames(t *testing.T, snap *chainledger.SnapshotFile, dataset string) []string {
333		t.Helper()
334		report, err := chainledger.TraceSources(snap, dataset)
335		if err != nil {
336			t.Fatalf("trace %q: %v", dataset, err)
337		}
338		roots := make([]string, 0, len(report.Sources))
339		for _, src := range report.Sources {
340			roots = append(roots, src.Root)
341		}
342		return roots
343	}
344	
345	// assertNoLeftoverTempFiles fails if the atomic-write temp pattern left any
346	// half snapshot behind in the target directory.
347	func assertNoLeftoverTempFiles(t *testing.T, dir string) {
348		t.Helper()
349		entries, err := os.ReadDir(dir)
350		if err != nil {
351			t.Fatalf("read target dir: %v", err)
352		}
353		for _, entry := range entries {
354			if strings.HasPrefix(entry.Name(), ".chainledger-") {
355				t.Errorf("rejected/failed save left a temporary file %q", filepath.Join(dir, entry.Name()))
356			}
357		}
358	}
359	
360	// writeRoundInput writes one source graph file and returns its path and exact
361	// bytes, so the test can later prove the source graph was never modified.
362	func writeRoundInput(t *testing.T, dir, name, content string) (path string, raw []byte) {
363		t.Helper()
364		path = filepath.Join(dir, name)
365		raw = []byte(content)
366		if err := os.WriteFile(path, raw, 0o644); err != nil {
367			t.Fatalf("write %s: %v", name, err)
368		}
369		return path, raw
370	}
371	
372	// Two valid but semantically different graphs: the same derived datasets
373	// "report"/"events" reach different root sources.
374	const concurrentGraphRootA = `{"datasets":[` +
375		`{"name":"report","upstreams":["events"]},` +
376		`{"name":"events","upstreams":["chain-A"]},` +
377		`{"name":"chain-A","upstreams":[]}]}`
378	
379	const concurrentGraphRootB = `{"datasets":[` +
380		`{"name":"report","upstreams":["events"]},` +
381		`{"name":"events","upstreams":["chain-B"]},` +
382		`{"name":"chain-B","upstreams":[]}]}`
383	
384	// TestCrossProcessSnapshotDifferentContentExactlyOneWins submits two
385	// independent command processes simultaneously against a not-yet-existing
386	// target, each reading a legal but semantically different graph. Exactly one
387	// must win; which one is not fixed. The test runs both launch orders and
388	// accepts either winner, fully checking outcomes against the winner each time.
389	func TestCrossProcessSnapshotDifferentContentExactlyOneWins(t *testing.T) {
390		wantA := mustSnapshotFromGraph(t, concurrentGraphRootA)
391		wantB := mustSnapshotFromGraph(t, concurrentGraphRootB)
392		if wantA.ContentID == wantB.ContentID {
393			t.Fatal("test setup: the two graphs must have different content identifiers")
394		}
395	
396		const rounds = 8
397		wins := map[string]int{"chain-A": 0, "chain-B": 0}
398		for round := 0; round < rounds; round++ {
399			dir := t.TempDir()
400			graphAPath, graphABytes := writeRoundInput(t, dir, "graph-a.json", concurrentGraphRootA)
401			graphBPath, graphBBytes := writeRoundInput(t, dir, "graph-b.json", concurrentGraphRootB)
402			target := filepath.Join(dir, "snapshot.json")
403			if _, err := os.Stat(target); !os.IsNotExist(err) {
404				t.Fatalf("round %d: target must not exist before the saves", round)
405			}
406	
407			// Alternate launch order; thanks to the gate both are always blocked
408			// together, so the order cannot predetermine the winner.
409			var first, second procResult
410			if round%2 == 0 {
411				first, second = launchConcurrentSnapshotPair(t, target, graphAPath, graphBPath)
412			} else {
413				first, second = launchConcurrentSnapshotPair(t, target, graphBPath, graphAPath)
414			}
415			results := []procResult{first, second}
416	
417			var winner, loser *procResult
418			for i := range results {
419				switch results[i].exitCode {
420				case 0:
421					if winner != nil {
422						t.Fatalf("round %d: both saves succeeded (%s and %s), want exactly one",
423							round, winner.label, results[i].label)
424					}
425					w := results[i]
426					winner = &w
427				default:
428					l := results[i]
429					loser = &l
430				}
431			}
432			if winner == nil {
433				t.Fatalf("round %d: both saves failed, want exactly one winner\nstderr1: %s\nstderr2: %s",
434					round, first.stderr, second.stderr)
435			}
436			if loser == nil {
437				t.Fatalf("round %d: no save was rejected", round)
438			}
439	
440			// Identify the winning graph from the path the winning command read.
441			var winnerRoot string
442			var winnerWant *chainledger.SnapshotFile
443			switch winner.sourceGraph {
444			case graphAPath:
445				winnerRoot, winnerWant = "chain-A", wantA
446			case graphBPath:
447				winnerRoot, winnerWant = "chain-B", wantB
448			default:
449				t.Fatalf("round %d: winner read unknown graph %q", round, winner.sourceGraph)
450			}
451			loserRoot := map[string]string{"chain-A": "chain-B", "chain-B": "chain-A"}[winnerRoot]
452			wins[winnerRoot]++
453	
454			// Winner: exit 0 and stdout contains ONLY the id of what it saved.
455			if winner.stdout != winnerWant.ContentID+"\n" {
456				t.Errorf("round %d: winner stdout = %q, want exactly %q",
457					round, winner.stdout, winnerWant.ContentID)
458			}
459			if winner.stderr != "" {
460				t.Errorf("round %d: winner stderr = %q, want empty", round, winner.stderr)
461			}
462			// Loser: non-zero exit, empty stdout, stderr explains the target
463			// already holds different content and names the target path.
464			if loser.exitCode == 0 {
465				t.Errorf("round %d: rejected save returned exit code 0, want non-zero", round)
466			}
467			if loser.stdout != "" {
468				t.Errorf("round %d: loser stdout = %q, want empty", round, loser.stdout)
469			}
470			if !strings.Contains(loser.stderr, "already holds a different snapshot") {
471				t.Errorf("round %d: loser stderr = %q, want it to explain the target already holds a different snapshot",
472					round, loser.stderr)
473			}
474			if !strings.Contains(loser.stderr, target) {
475				t.Errorf("round %d: loser stderr = %q, want it to name the target path %q",
476					round, loser.stderr, target)
477			}
478	
479			// The target must be one complete, readable snapshot — never a half
480			// file — and the winner's printed id, the file's contentId, and the
481			// stored graph must all describe the SAME graph.
482			finalBytes, err := os.ReadFile(target)
483			if err != nil {
484				t.Fatalf("round %d: target missing/unreadable after both saves: %v", round, err)
485			}
486			finalSnap, err := chainledger.ParseSnapshot(finalBytes)
487			if err != nil {
488				t.Fatalf("round %d: target is not a valid snapshot after the race:\n%s\nerr: %v",
489					round, finalBytes, err)
490			}
491			if finalSnap.ContentID != winnerWant.ContentID {
492				t.Errorf("round %d: target contentId %q != winner %q (loser root %s)",
493					round, finalSnap.ContentID, winnerWant.ContentID, loserRoot)
494			}
495			if !reflect.DeepEqual(finalSnap.Graph, winnerWant.Graph) {
496				t.Errorf("round %d: stored graph does not match the winning graph %q:\ngot:  %+v\nwant: %+v",
497					round, winnerRoot, finalSnap.Graph, winnerWant.Graph)
498			}
499			// The other version's root must not have leaked into the winner.
500			for _, ds := range finalSnap.Graph.Datasets {
501				if ds.Name == loserRoot {
502					t.Errorf("round %d: loser root %q leaked into the winning snapshot", round, loserRoot)
503				}
504			}
505			// Direct upstream chain preserved end to end: the shared derived
506			// dataset traces to the winner's root only.
507			if got := rootNames(t, finalSnap, "report"); !reflect.DeepEqual(got, []string{winnerRoot}) {
508				t.Errorf("round %d: report roots = %v, want [%s]", round, got, winnerRoot)
509			}
510			if got := rootNames(t, finalSnap, "events"); !reflect.DeepEqual(got, []string{winnerRoot}) {
511				t.Errorf("round %d: events roots = %v, want [%s]", round, got, winnerRoot)
512			}
513			// The on-disk bytes are exactly the canonical snapshot of the winner.
514			wantBytes, err := chainledger.MarshalSnapshot(winnerWant)
515			if err != nil {
516				t.Fatalf("marshal expected snapshot: %v", err)
517			}
518			if !bytes.Equal(finalBytes, wantBytes) {
519				t.Errorf("round %d: target bytes are not the canonical winner bytes", round)
520			}
521	
522			// Both source graphs remain byte-for-byte untouched.
523			if got, err := os.ReadFile(graphAPath); err != nil || !bytes.Equal(got, graphABytes) {
524				t.Errorf("round %d: source graph A was modified", round)
525			}
526			if got, err := os.ReadFile(graphBPath); err != nil || !bytes.Equal(got, graphBBytes) {
527				t.Errorf("round %d: source graph B was modified", round)
528			}
529			assertNoLeftoverTempFiles(t, dir)
530		}
531		t.Logf("rounds=%d winner distribution: chain-A=%d chain-B=%d (either winner is correct)",
532			rounds, wins["chain-A"], wins["chain-B"])
533	}
