535	// Two byte-different encodings of ONE graph: different record order, upstream
536	// order, a duplicated upstream, and JSON whitespace. Semantically identical,
537	// so they share one content id and one canonical byte form.
538	const equivalentGraphForm1 = `{"datasets":[` +
539		`{"name":"derived","upstreams":["root-b","root-a","root-b"]},` +
540		`{"name":"root-a","upstreams":[]},` +
541		`{"name":"root-b","upstreams":[]}]}`
542	
543	const equivalentGraphForm2 = `{
544	  "datasets": [
545	    { "name": "root-b", "upstreams": [ ] },
546	    { "name": "derived", "upstreams": ["root-a", "root-b"] },
547	    { "name": "root-a", "upstreams": [] }
548	  ]
549	}`
550	
551	// TestCrossProcessSnapshotSemanticallyEqualBothSucceed submits two independent
552	// processes simultaneously with semantically equal inputs (different record
553	// order, upstream order, duplicate upstream, whitespace). Both must succeed and
554	// report the same id, and the created snapshot follows the existing sorting
555	// and de-duplication rules.
556	func TestCrossProcessSnapshotSemanticallyEqualBothSucceed(t *testing.T) {
557		want1 := mustSnapshotFromGraph(t, equivalentGraphForm1)
558		want2 := mustSnapshotFromGraph(t, equivalentGraphForm2)
559		if want1.ContentID != want2.ContentID {
560			t.Fatalf("test setup: equivalent graphs got different ids %q vs %q",
561				want1.ContentID, want2.ContentID)
562		}
563		wantBytes, err := chainledger.MarshalSnapshot(want1)
564		if err != nil {
565			t.Fatalf("marshal canonical snapshot: %v", err)
566		}
567	
568		dir := t.TempDir()
569		graph1Path, _ := writeRoundInput(t, dir, "form1.json", equivalentGraphForm1)
570		graph2Path, graph2Raw := writeRoundInput(t, dir, "form2.json", equivalentGraphForm2)
571		target := filepath.Join(dir, "snapshot.json")
572	
573		first, second := launchConcurrentSnapshotPair(t, target, graph1Path, graph2Path)
574		for _, res := range []procResult{first, second} {
575			if res.exitCode != 0 {
576				t.Errorf("%s save of semantically equal content exited %d: %s",
577					res.label, res.exitCode, res.stderr)
578			}
579			if res.stdout != want1.ContentID+"\n" {
580				t.Errorf("%s stdout = %q, want exactly %q", res.label, res.stdout, want1.ContentID)
581			}
582			if res.stderr != "" {
583				t.Errorf("%s stderr = %q, want empty", res.label, res.stderr)
584			}
585		}
586	
587		finalBytes, err := os.ReadFile(target)
588		if err != nil {
589			t.Fatalf("target unreadable: %v", err)
590		}
591		finalSnap, err := chainledger.ParseSnapshot(finalBytes)
592		if err != nil {
593			t.Fatalf("target is not a valid snapshot: %v\n%s", err, finalBytes)
594		}
595		if finalSnap.ContentID != want1.ContentID {
596			t.Errorf("target contentId %q, want %q", finalSnap.ContentID, want1.ContentID)
597		}
598		if !bytes.Equal(finalBytes, wantBytes) {
599			t.Errorf("created snapshot bytes do not follow canonical sorting/dedup:\ngot:\n%s\nwant:\n%s",
600				finalBytes, wantBytes)
601		}
602		// Explicitly verify ordering and duplicate removal inside the graph.
603		gotNames := make([]string, 0, len(finalSnap.Graph.Datasets))
604		for _, ds := range finalSnap.Graph.Datasets {
605			gotNames = append(gotNames, ds.Name)
606		}
607		if !sort.StringsAreSorted(gotNames) {
608			t.Errorf("datasets not sorted by name: %v", gotNames)
609		}
610		for _, ds := range finalSnap.Graph.Datasets {
611			if !sort.StringsAreSorted(ds.Upstreams) {
612				t.Errorf("upstreams of %q not sorted: %v", ds.Name, ds.Upstreams)
613			}
614			seen := map[string]bool{}
615			for _, u := range ds.Upstreams {
616				if seen[u] {
617					t.Errorf("upstream %q duplicated under %q", u, ds.Name)
618				}
619				seen[u] = true
620			}
621		}
622		if got := rootNames(t, finalSnap, "derived"); !reflect.DeepEqual(got, []string{"root-a", "root-b"}) {
623			t.Errorf("derived roots = %v, want [root-a root-b]", got)
624		}
625		if got, err := os.ReadFile(graph2Path); err != nil || !bytes.Equal(got, graph2Raw) {
626			t.Errorf("source graph form2 was modified")
627		}
628		assertNoLeftoverTempFiles(t, dir)
629	}
630	
631	// saveOnce runs one snapshot command to completion, returning its result.
632	func saveOnce(t *testing.T, graphPath, target string) procResult {
633		t.Helper()
634		var stdout, stderr bytes.Buffer
635		cmd := exec.Command(snapshotCLIBin, "snapshot", graphPath, target)
636		cmd.Stdout, cmd.Stderr = &stdout, &stderr
637		if err := cmd.Run(); err != nil {
638			if cmd.ProcessState == nil {
639				t.Fatalf("seed snapshot failed to run: %v", err)
640			}
641		}
642		return procResult{
643			stdout:   stdout.String(),
644			stderr:   stderr.String(),
645			exitCode: cmd.ProcessState.ExitCode(),
646		}
647	}
648	
649	// TestCrossProcessSnapshotPreexistingSameContentUntouched seeds the target with
650	// a valid snapshot of the same content, then submits two simultaneous saves
651	// (each reading a different equivalent encoding). Both must succeed and the
652	// existing file must remain byte-for-byte and mtime identical — no rewrite.
653	func TestCrossProcessSnapshotPreexistingSameContentUntouched(t *testing.T) {
654		want := mustSnapshotFromGraph(t, equivalentGraphForm1)
655	
656		dir := t.TempDir()
657		graph1Path, _ := writeRoundInput(t, dir, "form1.json", equivalentGraphForm1)
658		graph2Path, graph2Raw := writeRoundInput(t, dir, "form2.json", equivalentGraphForm2)
659		target := filepath.Join(dir, "snapshot.json")
660	
661		seed := saveOnce(t, graph1Path, target)
662		if seed.exitCode != 0 {
663			t.Fatalf("seed snapshot exited %d: %s", seed.exitCode, seed.stderr)
664		}
665		seedBytes, err := os.ReadFile(target)
666		if err != nil {
667			t.Fatalf("read seed snapshot: %v", err)
668		}
669		infoBefore, err := os.Stat(target)
670		if err != nil {
671			t.Fatalf("stat seed snapshot: %v", err)
672		}
673	
674		first, second := launchConcurrentSnapshotPair(t, target, graph1Path, graph2Path)
675		for _, res := range []procResult{first, second} {
676			if res.exitCode != 0 {
677				t.Errorf("%s save over identical content exited %d: %s",
678					res.label, res.exitCode, res.stderr)
679			}
680			if res.stdout != want.ContentID+"\n" {
681				t.Errorf("%s stdout = %q, want exactly %q", res.label, res.stdout, want.ContentID)
682			}
683			if res.stderr != "" {
684				t.Errorf("%s stderr = %q, want empty", res.label, res.stderr)
685			}
686		}
687	
688		gotBytes, err := os.ReadFile(target)
689		if err != nil {
690			t.Fatalf("read target after saves: %v", err)
691		}
692		if !bytes.Equal(gotBytes, seedBytes) {
693			t.Errorf("identical-content concurrent saves rewrote the target:\nbefore: %x\nafter:  %x",
694				seedBytes, gotBytes)
695		}
696		infoAfter, err := os.Stat(target)
697		if err != nil {
698			t.Fatalf("stat target after saves: %v", err)
699		}
700		if !infoAfter.ModTime().Equal(infoBefore.ModTime()) {
701			t.Errorf("identical-content concurrent saves changed mtime: %s -> %s",
702				infoBefore.ModTime(), infoAfter.ModTime())
703		}
704		// The untouched file still reads as the same valid snapshot.
705		if _, err := chainledger.ParseSnapshot(gotBytes); err != nil {
706			t.Errorf("preexisting snapshot unreadable after concurrent saves: %v", err)
707		}
708		if got, err := os.ReadFile(graph2Path); err != nil || !bytes.Equal(got, graph2Raw) {
709			t.Errorf("source graph form2 was modified")
710		}
711		assertNoLeftoverTempFiles(t, dir)
712	}
